node -e "
const fs = require('fs');
const src = fs.readFileSync('src/services/authoredChartExplanations.ts','utf8');
const count = (re) => (src.match(re) || []).length;
console.log('regimes: occurrences', count(/regimes:/g));
console.log('evolution: occurrences', count(/evolution:/g));
// uniqueness of passages
const regimes = [...src.matchAll(/regimes: '((?:[^'\\\\]|\\\\.)*)'/g)].map(m=>m[1]);
const evolutions = [...src.matchAll(/evolution: '((?:[^'\\\\]|\\\\.)*)'/g)].map(m=>m[1]);
console.log('regimes captured', regimes.length, 'unique', new Set(regimes).size);
console.log('evolution captured', evolutions.length, 'unique', new Set(evolutions).size);
const all = regimes.concat(evolutions);
console.log('combined unique', new Set(all).size, 'of', all.length);
const shortest = all.slice().sort((a,b)=>a.length-b.length)[0];
console.log('shortest passage length', shortest.length);
// BODIES key count
const bodies = src.match(/const BODIES[^{]*\{([\s\S]*?)\n\};/)[1];
console.log('BODIES keys', (bodies.match(/^\s{2}(\w+): \{/gm)||[]).length);
const signs = src.match(/const SIGN_CORES[^{]*\{([\s\S]*?)\n\};/)[1];
console.log('SIGN keys', (signs.match(/^\s{2}(\w+): \{/gm)||[]).length);
const aspects = src.match(/const ASPECT_CORES[^{]*\{([\s\S]*?)\n\};/)[1];
console.log('ASPECT keys', (aspects.match(/^\s{2}(\w+): \{/gm)||[]).length);
const houses = src.match(/const HOUSE_CORES[^=]*=\s*\[([\s\S]*?)\n\];/)[1];
console.log('HOUSE entries', (houses.match(/\{ what:/g)||[]).length);
"

