220	): AuthoredExplanation {
221	  const ancientLine = core.ancient
222	    ? ' This is one of the seven classical planets, watched and named thousands of years before telescopes existed.'
223	    : core.modern
224	      ? ' This is a modern discovery: no ancient astrologer knew it existed, and its meaning is a later symbolic assignment, not an ancient tradition.'
225	      : '';
226	  const intro = `${nameSentence}${facts ? ' ' + facts : ''} ${core.what}${ancientLine} ${core.regimes} ${core.evolution} ${CONTEXT_LINE}`;
227	  const middle = `${core.trad} ${core.why}`;
228	  const closing = `As you sit with this, try it on rather than take it on faith: ${core.q}`;
229	  return { title, text: [intro, middle, closing].join('\n\n'), targets };
230	}
