232	function bodyFacts(chart: NatalChartResult, bodyName: string): string {
233	  const body = chart.natalBodies.find(candidate => candidate.name === bodyName);
234	  if (!body) return '';
235	  if (chart.input.birthTimeUnknown) {
236	    const moonNote = bodyName === 'Moon'
237	      ? ' The Moon moves quickly, so its exact birth degree could be several degrees away from the value shown.'
238	      : '';
239	    return `Because the birth time is unknown, this chart is calculated for noon as an approximation.${moonNote} Houses and angles cannot be determined without a birth time.`;
240	  }
241	  const facts = [`Your ${body.name} sits at ${body.fullDegText}`];
242	  if (Number.isFinite(body.house) && body.house >= 1 && body.house <= 12) {
243	    facts.push(`in your ${ordinal(body.house)} house`);
244	  }
245	  return facts.join(' ') + '.';
246	}
