248	function resolveDatedTarget(chart: NatalChartResult, canonical: string): { name: string; facts: string } | null {
249	  if (!isDatedSkyTarget(canonical) || !chart.currentSky) return null;
250	  const body = chart.currentSky.bodies.find(candidate => candidate.target === canonical);
251	  const observed = new Date(chart.currentSky.observedAt);
252	  const observedText = Number.isFinite(observed.getTime()) ? observed.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : chart.currentSky.observedAt;
253	  if (body) {
254	    const natal = chart.natalBodies.find(candidate => candidate.name === body.name);
255	    const natalApproximate = body.name === 'Moon' && chart.input.birthTimeUnknown;
256	    const natalText = natal && !natalApproximate
257	      ? `, whereas your natal ${body.name} sits at ${natal.fullDegText}`
258	      : natalApproximate
259	        ? ', whereas your natal Moon position is an approximation because the birth time is unknown'
260	        : '';
261	    return { name: body.name, facts: `As observed at ${observedText}, ${body.name} is at ${body.fullDegText} in the current sky${natalText}. The sky keeps moving; today's position and your birth position are two different photographs, not one placement.` };
262	  }
263	  const aspect = chart.currentSky.aspects.find(candidate => candidate.name === canonical);
264	  if (aspect) {
265	    const fromBody = chart.currentSky.bodies.find(candidate => candidate.target === aspect.from);
266	    return { name: aspect.type, facts: `As observed at ${observedText}, ${fromBody?.name ?? chartTargetLabel(aspect.from)} forms a ${aspect.type.toLowerCase()} with your natal ${chartTargetLabel(aspect.to)} (within ${Math.abs(aspect.orb).toFixed(1)}°). This is a temporary sky relationship, not a natal one.` };
267	  }
268	  return null;
269	}
