271	export function getAuthoredChartExplanation(chart: NatalChartResult, target?: string, framing?:string): AuthoredExplanation {
272	  const name = sanitizeName(chart.input.name);
273	  const introduction = framing ?? 'Here is the lesson you asked about.';
274	  const nameSentence = name ? `${name}, ${introduction.charAt(0).toLowerCase()+introduction.slice(1)}` : introduction;
275	  const canonical = target ? resolveChartTarget(target, chart) : null;
276	  if (!canonical) {
277	    return buildLesson(GENERAL_TITLE, GENERAL_LESSON, '', nameSentence, []);
278	  }
279	  const label = chartTargetLabel(canonical);
280	
281	  const dated = resolveDatedTarget(chart, canonical);
282	  if (dated) {
283	    const core = BODIES[dated.name] ?? ASPECT_CORES[dated.name] ?? GENERAL_LESSON;
284	    return buildLesson(`Now: ${label}`, core, dated.facts, nameSentence, [canonical]);
285	  }
286	
287	  const natalBody = chart.natalBodies.find(candidate => candidate.name === canonical || candidate.name === label);
288	  if (natalBody) {
289	    const core = BODIES[natalBody.name] ?? BODIES[label] ?? null;
290	    if (core) {
291	      return buildLesson(`${natalBody.name} in your chart`, core, bodyFacts(chart, natalBody.name), nameSentence, [canonical]);
292	    }
293	  }
294	
295	  const sign = ZODIAC_SIGNS.find(candidate => candidate.name === label || candidate.name === canonical);
296	  if (sign) {
297	    const facts = 'Seasonal imagery here comes from the tropical zodiac\u2019s northern-hemisphere origins; the constellations and the local seasons where you live do not match these labels one-to-one.';
298	    return buildLesson(`${sign.name}, the ${sign.element} sign`, SIGN_CORES[sign.name], facts, nameSentence, [canonical]);
299	  }
300	
301	  const houseMatch = /House (\d{1,2})$/i.exec(canonical);
302	  if (houseMatch) {
303	    const num = Number(houseMatch[1]);
304	    if (num >= 1 && num <= 12 && !chart.input.birthTimeUnknown) {
305	      const topic = HOUSE_TOPICS[num - 1];
306	      const core = HOUSE_CORES[num - 1];
307	      return buildLesson(`Your ${ordinal(num)} house`, core, `${HOUSE_SYSTEMS_CONTEXT} Tradition files the ${topic.domain} here.`, nameSentence, [canonical]);
308	    }
309	  }
310	
311	  const aspect = chart.aspectChords.find(candidate => candidate.name === canonical);
312	  if (aspect) {
313	    const core = ASPECT_CORES[aspect.type] ?? GENERAL_LESSON;
314	    const fromBody = chart.natalBodies.find(candidate => candidate.name === aspect.from);
315	    const toBody = chart.natalBodies.find(candidate => candidate.name === aspect.to);
316	    const facts = `In your chart, ${aspect.from} ${aspect.type.toLowerCase()} ${aspect.to} (within ${Math.abs(aspect.orb).toFixed(1)}°)${fromBody ? `, with ${aspect.from} at ${fromBody.fullDegText}` : ''}${toBody ? ` and ${aspect.to} at ${toBody.fullDegText}` : ''}.`;
317	    return buildLesson(`${aspect.from} ${aspect.type.toLowerCase()} ${aspect.to}`, core, facts, nameSentence, [canonical]);
318	  }
319	
320	  if (!chart.input.birthTimeUnknown && /^House \d{1,2}$/i.test(label)) return buildLesson(GENERAL_TITLE, GENERAL_LESSON, '', nameSentence, []);
321	  return buildLesson(GENERAL_TITLE, GENERAL_LESSON, '', nameSentence, []);
322	}
