324	export function getAuthoredConversationClose(name: string): AuthoredExplanation {
325	  const safe = sanitizeName(name);
326	  const greeting = safe ? `${safe}, ` : '';
327	  const text = [
328	    `${greeting}I would love to keep going with you, and there are two ways to do that. I can sit with you in a longer guided conversation, where we wander through whatever is on your mind and look at it through your chart together, question by question.`,
329	    'Or I can compose a personal keepsake reading: a full, written piece about your sky that you can keep, reread and return to whenever you like. Each of these is prepared with real care rather than a quick answer, which is why they are part of the paid offerings; the live quote at checkout shows the current price before you decide anything.',
330	    'Meanwhile, the free chart right here is still rich: click any planet, sign, house or aspect and I will teach you what the tradition says about it. What would you like to explore together first?',
331	  ].join('\n\n');
332	  return { title: 'Explore with Natally', text, targets: [] };
333	}
