335	export type UpsellCloseVariant = 'default' | 'souvenir';
336	
337	const UPSELL_CLOSES: Record<UpsellCloseVariant, readonly string[]> = {
338	  default: [
339	    'This is the part where I make my one smooth pitch, and I will own it: you have seen the pieces, and a personal reading is where they become your story. Purchase Cr through Top Up, bring the question you actually came with, and I will give it my full attention.',
340	    'I will say it plainly, because your chart has earned it: the free lessons are the tour, and the personal reading is the sitting. Spend Cr on one and we will read this sky together, question by question, until it is yours.',
341	    'No countdown timers and no pressure — just confidence: whenever you want the whole picture, purchase Cr through Top Up and ask me for your personal reading. The sky is not going anywhere, and frankly, neither am I.',
342	  ],
343	  souvenir: [
344	    'Here is my favorite kind of sales line, the honest one: let this reading become a souvenir. You keep the PDF, and the persisted interactive vignette frozen in time reopens the atelier exactly as it stood, waiting on your account whenever you want to walk back in.',
345	    'Some evenings deserve better than a scroll through history. Create your souvenir: the PDF puts the reading in your hands, and the persisted interactive vignette frozen in time keeps the atelier unchanged, ready to re-enter like a room you once stood in.',
346	    'One confident offer, made once: turn this into a souvenir. The PDF keeps the words; the persisted interactive vignette frozen in time keeps the experience; your account keeps the door unlocked.',
347	  ],
348	};
349	const upsellCloseCursor: Record<UpsellCloseVariant, number> = { default: 0, souvenir: 0 };
350	
351	/** Frozen authored upsell close for a chart. Pure authored text: no network, no LLM, no audio.
352	 *  Light in-file rotation per variant so consecutive lessons never repeat the same close verbatim. */
353	export function getAuthoredUpsellClose(chart: NatalChartResult, variant: 'default' | 'souvenir'): string {
354	  const lines = UPSELL_CLOSES[variant] ?? UPSELL_CLOSES.default;
355	  const index = upsellCloseCursor[variant] % lines.length;
356	  upsellCloseCursor[variant] = (index + 1) % lines.length;
357	  const safe = sanitizeName(chart.input.name);
358	  if (!safe) return lines[index];
359	  const body = /^I\b/.test(lines[index]) ? lines[index] : lines[index].charAt(0).toLocaleLowerCase(undefined) + lines[index].slice(1);
360	  return `${safe}, ${body}`;
361	}

