47	const choose = <T,>(values:readonly T[]):T => values[Math.floor(Math.random()*values.length)];
48	function pickPhrase(phrases:readonly Phrase[], cycle:PhraseCycle):Phrase {
49	  const unused=phrases.filter(phrase=>!cycle.used.has(phrase.id));
50	  return choose(unused.length ? unused : phrases.filter(phrase=>phrase.id!==cycle.last));
51	}
52	function rememberPhrase(phrases:readonly Phrase[], cycle:PhraseCycle, id:string) {
53	  if (cycle.used.size===phrases.length) cycle.used.clear();
54	  cycle.used.add(id);cycle.last=id;
55	}
56	/** Compose the next upsell close after a lesson, skipping a verbatim repeat of the last delivered
57	 *  close (the composer's in-file rotation supplies a different line on the second call). */
58	function nextUpsellClose(compose:()=>string, last:string|null):string {
59	  const candidate=compose();
60	  if (last===null || candidate!==last) return candidate;
61	  const alternate=compose();
62	  return alternate!==last ? alternate : candidate;
63	}
