69	  if (!Number.isInteger(settings.minAnswers) || settings.minAnswers<2 || settings.minAnswers>4) throw new Error('VITE_EDUCATION_INVITE_MIN_ANSWERS must be an integer from 2 through 4.');
70	  if (!Number.isInteger(settings.maxAnswers) || settings.maxAnswers<settings.minAnswers || settings.maxAnswers>4) throw new Error('VITE_EDUCATION_INVITE_MAX_ANSWERS must be an integer from the configured minimum through 4.');
71	  const thresholds=Array.from({length:settings.maxAnswers-settings.minAnswers+1},(_,index)=>settings.minAnswers+index);
72	  const nextThreshold = (previous?:number) => choose(thresholds.length>1 ? thresholds.filter(value=>value!==previous) : thresholds);
